package main

import "fmt"

func choose(word string, next, k int, path []byte, results *[]string) {
	if len(path) == k {
		*results = append(*results, string(path)) // string(path) copies the bytes
		return
	}
	if next == len(word) {
		return
	}
	path = append(path, word[next])
	choose(word, next+1, k, path, results)
	path = path[:len(path)-1]
	choose(word, next+1, k, path, results)
}

func main() {
	var word string
	var k int
	fmt.Scan(&word, &k)
	var results []string
	choose(word, 0, k, []byte{}, &results)
	for _, r := range results {
		fmt.Println(r)
	}
}

steps.body:
**Depth-first search** (DFS) goes as deep as possible along one path before backing up to try another. Recursion does the backing up for you. On a grid stored as a `[]string` of `#` (land) and `.` (water), a DFS from one land cell floods its whole island.

```go harness
package main

import "fmt"

{{code}}

func main() {
	grid := []string{"##..#", "#....", "..#.."}
	visited := make([][]bool, len(grid))
	for r := range grid {
		visited[r] = make([]bool, len(grid[r]))
	}
	islands := 0
	for r := range grid {
		for c := 0; c < len(grid[r]); c++ {
			if grid[r][c] == '#' && !visited[r][c] {
				dfs(grid, visited, r, c)
				islands++
			}
		}
	}
	fmt.Println("Islands:", islands)
}
```

```go
var dr = []int{-1, 1, 0, 0}
var dc = []int{0, 0, -1, 1}

func dfs(grid []string, visited [][]bool, r, c int) {
	if r < 0 || r >= len(grid) || c < 0 || c >= len(grid[r]) {
		return // off the grid
	}
	if grid[r][c] != '#' || visited[r][c] {
		return
	}
	visited[r][c] = true
	for i := 0; i < 4; i++ {
		dfs(grid, visited, r+dr[i], c+dc[i])
	}
}
```

- Check bounds **before** indexing, or `grid[r][c]` panics with index out of range.
- Mark a cell visited before recursing, or two neighbors keep calling each other forever.
- `dr` and `dc` list the four moves (up, down, left, right), so one loop replaces four calls.

Make `dfs` a top-level function that takes the grid and `visited` as parameters. A function literal cannot call itself unless you declare it first with `var dfs func(r, c int)`. To **count regions**, loop over every cell and start a new DFS at each unvisited land cell.

