package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

var dr = []int{-1, 1, 0, 0}
var dc = []int{0, 0, -1, 1}

func dfs(grid []string, visited [][]bool, r, c int) {
	if r < 0 || r >= len(grid) || c < 0 || c >= len(grid[r]) {
		return
	}
	if grid[r][c] != '#' || visited[r][c] {
		return
	}
	visited[r][c] = true
	for i := 0; i < 4; i++ {
		dfs(grid, visited, r+dr[i], c+dc[i])
	}
}

func main() {
	var grid []string
	scanner := bufio.NewScanner(os.Stdin)
	for scanner.Scan() {
		if line := strings.TrimSpace(scanner.Text()); line != "" {
			grid = append(grid, line)
		}
	}
	visited := make([][]bool, len(grid))
	for r := range grid {
		visited[r] = make([]bool, len(grid[r]))
	}
	islands := 0
	for r := range grid {
		for c := 0; c < len(grid[r]); c++ {
			if grid[r][c] == '#' && !visited[r][c] {
				dfs(grid, visited, r, c)
				islands++
			}
		}
	}
	fmt.Println("Islands:", islands)
}

